  "name": "secret-guard",
  "version": "0.1.0",
  "description": "Hides your project's .env values from tool results before Claude reads them",
  "author": {
    "name": "Chien Vu Minh"
  },
  "userConfig": {
    "mode": {
      "type": "string",
      "title": "Mode",
