      "default": "value",
      "options": [
        "value",
        "command"
      ]
    },
    "identifierKeys": {
      "type": "string",
      "title": "Identifier keys",
      "description": "Comma-separated .env keys that hold names, not secrets (a login name that appears in ordinary paths); never hidden.",
